GROUP_WINDOW = timedelta(seconds=5)


def group_existing_movements(apps, schema_editor):
    """
    Cada movimiento existente pasa a ser línea de una operación. Los ajustes de un recuento comparten
    la operación del recuento; el resto se agrupa si tiene mismo usuario, tipo, motivo y nota y se creó
    a pocos segundos del primero del grupo (un lote), y las anulaciones van cada una por su lado.
    """
    Movement = apps.get_model('stock', 'StockMovement')
    Operation = apps.get_model('stock', 'StockOperation')
    by_count, open_groups = {}, {}

    def new_operation(m, **extra):
        fields = {'kind': m.kind, 'reason': m.reason, 'note': m.note, 'created_by_id': m.created_by_id, **extra}
        op = Operation.objects.create(**fields)
        Operation.objects.filter(pk=op.pk).update(created_at=m.created_at)  # auto_now_add pisa el valor al crear
        return op

    for m in Movement.objects.order_by('id'):
        if m.stock_count_id:
            op = by_count.get(m.stock_count_id) or new_operation(m, stock_count_id=m.stock_count_id, note=f'Recuento #{m.stock_count_id}')
            by_count[m.stock_count_id] = op
        elif m.reverses_id:
            op = new_operation(m)
        else:
            key = (m.created_by_id, m.kind, m.reason, m.note)
            group = open_groups.get(key)
            if group and m.created_at - group['start'] <= GROUP_WINDOW and m.variant_id not in group['variants']:
                op = group['op']
            else:
                op = new_operation(m)
                group = open_groups[key] = {'op': op, 'start': m.created_at, 'variants': set()}
            group['variants'].add(m.variant_id)
        Movement.objects.filter(pk=m.pk).update(operation_id=op.pk)


